import ast, hashlib
MAIN = WORKDIR / 'main.py'
EXPECTED_MAIN_SHA256 = '325e4144cbb0f0ff4782830934c9634e585f502b8162f4d9917489b740750259'
source_bytes = MAIN.read_bytes().replace(b'\r\n', b'\n').rstrip(b'\n') + b'\n'; MAIN.write_bytes(source_bytes)
actual = hashlib.sha256(source_bytes).hexdigest()
assert actual == EXPECTED_MAIN_SHA256, f'main.py integrity check failed: {actual}'
compile(source_bytes, 'main.py', 'exec')
tree = ast.parse(source_bytes)
last = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))][-1]
print('sha256 OK:', actual); print('entry point (last callable):', last)


import gzip, io, tarfile
from IPython.display import FileLink, display
ARCHIVE = WORKDIR / 'submission.tar.gz'
with ARCHIVE.open('wb') as file:
    with gzip.GzipFile(filename='', mode='wb', fileobj=file, mtime=0) as compressed:
        with tarfile.open(fileobj=compressed, mode='w', format=tarfile.GNU_FORMAT) as tar:
            info = tarfile.TarInfo('main.py'); info.size, info.mode, info.mtime = len(source_bytes), 0o644, 0
            tar.addfile(info, io.BytesIO(source_bytes))
with tarfile.open(ARCHIVE) as tar:
    assert tar.getnames() == ['main.py'] and tar.extractfile('main.py').read() == source_bytes
print('archive:', ARCHIVE, ARCHIVE.stat().st_size, 'bytes'); display(FileLink('submission.tar.gz'))
